SELECT COALESCE(member_stats.joined_count, 0)
         + COALESCE(invitation_stats.pending_count, 0) AS occupied_count,
       COALESCE(invitee_membership.joined_elsewhere, 0) AS joined_elsewhere,
       COALESCE(duplicate_invitation.duplicate_pending, 0) AS duplicate_pending
FROM (SELECT 1 AS seed) seed
LEFT JOIN (
    SELECT COUNT(*) AS joined_count
    FROM selection_team_member member
    WHERE member.team_id = #{teamId}
      AND member.member_status IN ('JOINED', 'LOCKED')
) member_stats ON 1 = 1
LEFT JOIN (
    SELECT COUNT(*) AS pending_count
    FROM team_invitation invitation
    WHERE invitation.team_id = #{teamId}
      AND invitation.invitation_status = 'PENDING'
      AND invitation.expires_at > CURRENT_TIMESTAMP(3)
) invitation_stats ON 1 = 1
LEFT JOIN (
    SELECT COUNT(*) AS joined_elsewhere
    FROM selection_team_member member
    WHERE member.batch_id = #{batchId}
      AND member.student_id = #{inviteeStudentId}
      AND member.member_status IN ('JOINED', 'LOCKED')
) invitee_membership ON 1 = 1
LEFT JOIN (
    SELECT COUNT(*) AS duplicate_pending
    FROM team_invitation invitation
    WHERE invitation.team_id = #{teamId}
      AND invitation.invitee_student_id = #{inviteeStudentId}
      AND invitation.invitation_status = 'PENDING'
      AND invitation.expires_at > CURRENT_TIMESTAMP(3)
) duplicate_invitation ON 1 = 1

